{"path":"events.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Gatherings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6A4CFF;--muted:#6b7280;--bg:#0f1724;--card:#0b1220;--glass:rgba(255,255,255,0.04)}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef8;background:linear-gradient(180deg,var(--bg),#061021);min-height:100vh}
    .wrap{max-width:980px;margin:32px auto;padding:28px}
    nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#9B7CFF);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    .navlinks{display:flex;gap:14px}
    .navlinks a{color:#cfe8ff;text-decoration:none;padding:6px 10px;border-radius:8px}
    .navlinks a[href='events.html']{background:rgba(255,255,255,0.03)}
    header.hero{background:linear-gradient(135deg,rgba(106,76,255,0.12),rgba(0,0,0,0.06));padding:20px;border-radius:14px;margin-bottom:18px}
    .hero-grid{display:grid;grid-template-columns:1fr 320px;gap:18px;align-items:start}
    .intro h1{margin:0 0 8px 0;color:white;font-size:22px}
    .intro p{margin:0;color:var(--muted)}
    .pattern{position:absolute;right:0;top:6px;opacity:0.12}
    .card{background:var(--card);padding:14px;border-radius:12px;color:#d9e9ff}
    .next-event{display:flex;flex-direction:column;gap:8px}
    .when{font-weight:700;color:white}
    .countdown{display:flex;gap:8px}
    .pill{background:var(--glass);padding:10px;border-radius:8px;min-width:56px;text-align:center}
    .calendar{margin-top:12px}
    .event-item{display:flex;justify-content:space-between;padding:10px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);margin-bottom:8px}
    .muted{color:var(--muted);font-size:13px}
    .cta{display:inline-block;margin-top:12px;background:var(--accent);color:white;padding:10px 12px;border-radius:10px;text-decoration:none}
    .mood{display:flex;gap:8px;margin-top:14px}
    .mood button{background:transparent;border:1px solid rgba(255,255,255,0.06);color:#dbeafe;padding:8px 10px;border-radius:10px;cursor:pointer}
    .mood button.active{border-color:rgba(255,255,255,0.18);background:rgba(106,76,255,0.12)}
    footer{margin-top:24px;color:var(--muted);font-size:13px}
    .disclaimer{margin-top:10px;color:#ffd9d9;background:rgba(255,13,13,0.04);padding:10px;border-radius:8px}
    /* decorative svg */
    .decor{position:absolute;left:-40px;top:160px;opacity:0.08}
  </style>
</head>
<body>
  <div class='wrap'>
    <nav>
      <div class='brand'>
        <div class='logo'>SB</div>
        <div>
          <div style='font-weight:700;color:white'>{{BUSINESS_NAME}}</div>
          <div style='font-size:12px;color:var(--muted)'>A richer pause in {{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <div class='navlinks'>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html'>One-on-One</a>
        <a href='pricing.html'>Invest</a>
        <a href='about.html'>Story</a>
        <a href='book.html'>Reserve</a>
      </div>
    </nav>

    <header class='hero'>
      <div class='hero-grid'>
        <div class='intro'>
          <h1>Live journeys for small groups — bring your attention</h1>
          <p>Drop into a held sound field with tuned bowls, tuned voice, and space for rest. Choose an evening to lean into unwinding, brightening, or regrouping.</p>
          <div style='margin-top:10px'>
            <a class='cta' href='book.html'>See available dates</a>
            <a class='cta' style='background:transparent;border:1px solid rgba(255,255,255,0.06);margin-left:8px' href='faq.html'>Who this is for</a>
          </div>
          <div class='mood' aria-label='Mood selector' role='tablist'>
            <button data-mood='heavy' class='active'>Heavy</button>
            <button data-mood='rattled'>Rattled</button>
            <button data-mood='flat'>Flat</button>
            <button data-mood='light'>Light</button>
          </div>
        </div>

        <div class='card next-event' aria-live='polite'>
          <div class='when'>Next gathering</div>
          <div id='nextTitle' style='font-size:16px;font-weight:700;color:white'>Evening Drift — Community Flow</div>
          <div class='muted'>Saturday • Feb 28 • 7:00pm</div>
          <div class='countdown' style='margin-top:10px'>
            <div class='pill'><div id='d'>--</div><div class='muted'>days</div></div>
            <div class='pill'><div id='h'>--</div><div class='muted'>hrs</div></div>
            <div class='pill'><div id='m'>--</div><div class='muted'>min</div></div>
          </div>
          <a id='nextCta' class='cta' href='book.html' style='display:block;text-align:center;margin-top:12px'>Reserve this spot</a>
          <div class='disclaimer'>Please review contraindications before booking — pregnancy, active seizures, recent head injury, or implanted electric devices may require consultation.</div>
        </div>
      </div>
      <svg class='pattern' width='180' height='120' viewBox='0 0 180 120' fill='none' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>
        <defs>
          <linearGradient id='g1' x1='0' x2='1'>
            <stop offset='0' stop-color='#6A4CFF' stop-opacity='0.9'/>
            <stop offset='1' stop-color='#9B7CFF' stop-opacity='0.6'/>
          </linearGradient>
        </defs>
        <rect x='0' y='0' width='180' height='120' rx='12' fill='url(#g1)' opacity='0.14'></rect>
        <g fill='white' opacity='0.06'>
          <circle cx='30' cy='30' r='18'/>
          <circle cx='80' cy='55' r='10'/>
          <circle cx='130' cy='20' r='6'/>
        </g>
      </svg>
    </header>

    <main>
      <section class='card calendar'>
        <h3 style='margin:0 0 12px 0;color:white'>Upcoming gatherings</h3>
        <div class='event-item'>
          <div>
            <div style='font-weight:700'>Sunday Morning Ease</div>
            <div class='muted'>Sun • Mar 2 • 9:30am • 60 min</div>
          </div>
          <div style='text-align:right'>
            <div class='muted'>Small circle</div>
            <div style='margin-top:8px'><a class='cta' href='book.html'>Join</a></div>
          </div>
        </div>
        <div class='event-item'>
          <div>
            <div style='font-weight:700'>Midweek Reset</div>
            <div class='muted'>Wed • Mar 5 • 6:30pm • 75 min</div>
          </div>
          <div style='text-align:right'>
            <div class='muted'>Seated + mats</div>
            <div style='margin-top:8px'><a class='cta' href='book.html'>Reserve</a></div>
          </div>
        </div>
        <div class='event-item'>
          <div>
            <div style='font-weight:700'>Liminal Night — five bowls</div>
            <div class='muted'>Sat • Mar 8 • 8:00pm • 90 min</div>
          </div>
          <div style='text-align:right'>
            <div class='muted'>Low lighting</div>
            <div style='margin-top:8px'><a class='cta' href='book.html'>Grab a spot</a></div>
          </div>
        </div>
        <div class='muted' style='margin-top:8px'>More dates added weekly. If a session is full, add your name to the waitlist on the booking page.</div>
      </section>

      <section style='margin-top:18px'>
        <div class='card'>
          <h3 style='margin:0 0 10px 0;color:white'>Find the right session for your mood</h3>
          <div id='recommend' style='color:#dfeeff'>We recommend a guided evening with anchored breath cycles and long bowl tones to steady the nervous system.</div>
          <div style='margin-top:10px'>
            <a id='recCta' class='cta' href='book.html'>Book a guided evening</a>
          </div>
        </div>
      </section>

    </main>

    <footer>
      <div>Questions? Call {{PHONE}} or email <a href='mailto:{{EMAIL}}' style='color:#dbeafe'>{{EMAIL}}</a></div>
      <div class='muted' style='margin-top:6px'>Contraindications: please consult us if you have epilepsy, recent head trauma, are pregnant, or have any implanted electronic device. Not a substitute for medical care.</div>
    </footer>
  </div>

  <script>
    // Countdown to next event (example date)
    const target = new Date();
    target.setDate(target.getDate() + 8);
    target.setHours(19,0,0,0);

    function updateCountdown(){
      const now = new Date();
      const diff = Math.max(0,target - now);
      const days = Math.floor(diff/86400000);
      const hrs = Math.floor((diff%86400000)/3600000);
      const mins = Math.floor((diff%3600000)/60000);
      document.getElementById('d').textContent = days;
      document.getElementById('h').textContent = String(hrs).padStart(2,'0');
      document.getElementById('m').textContent = String(mins).padStart(2,'0');
    }
    updateCountdown();
    setInterval(updateCountdown,60000);

    // Mood-to-Method micro-morph
    const moods = document.querySelectorAll('.mood button');
    const recommend = document.getElementById('recommend');
    const recCta = document.getElementById('recCta');
    const nextTitle = document.getElementById('nextTitle');

    const map = {
      heavy: {text:'Slow, long-tone evenings: deep bowl sustain and anchored breath to lower tension.',cta:'Reserve a grounding seat',title:'Evening Drift — Community Flow'},
      rattled: {text:'A short, focused mini-session with voice-led pacing to settle a busy mind.',cta:'Book a quick settle',title:'Midweek Reset'},
      flat: {text:'Light, uplifting harmonics with intervals of guided movement to nudge circulation.',cta:'Choose a bright session',title:'Sunday Morning Ease'},
      light: {text:'An open sound playground with playful overtones and space to celebrate.',cta:'Claim a playful spot',title:'Liminal Night — five bowls'}
    };

    moods.forEach(btn=>btn.addEventListener('click',()=>{
      moods.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const m = btn.dataset.mood;
      recommend.style.opacity=0;setTimeout(()=>{recommend.textContent=map[m].text;recommend.style.opacity=1;},220);
      recCta.textContent=map[m].cta;
      nextTitle.textContent=map[m].title;
    }));
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>One-on-One Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#FF7A9A;--bg:#071022;--panel:#071522;--muted:#9fb0c8}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,var(--bg),#021018);color:#e8f7ff}
    .wrap{max-width:960px;margin:28px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#FFB3C9);display:flex;align-items:center;justify-content:center;color:#1b1b1b;font-weight:800}
    nav a{color:#cfe8ff;text-decoration:none;margin-left:12px}
    .lead{margin-top:18px;padding:18px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:16px}
    .panel{background:var(--panel);padding:14px;border-radius:12px}
    .selector{display:flex;gap:10px;flex-wrap:wrap}
    .selector button{background:transparent;border:1px solid rgba(255,255,255,0.04);padding:10px 12px;border-radius:10px;color:#dbeafe;cursor:pointer}
    .selector button.active{background:linear-gradient(90deg,rgba(255,122,154,0.12),rgba(255,179,201,0.08));border-color:rgba(255,122,154,0.24)}
    .method h3{margin:0;color:#fff}
    .method p{color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;background:var(--accent);color:#111;padding:10px 12px;border-radius:10px;text-decoration:none}
    .disclaimer{margin-top:12px;color:#ffd9d9;background:rgba(255,13,13,0.04);padding:10px;border-radius:8px}
    .tiny{font-size:13px;color:var(--muted)}
    .svg-decor{position:fixed;right:18px;bottom:18px;opacity:0.06}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div style='display:flex;gap:12px;align-items:center'>
        <div class='logo'>OP</div>
        <div>
          <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
          <div style='font-size:12px;color:var(--muted)'>Personal sessions in {{CITY}}</div>
        </div>
      </div>
      <div>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html'>One-on-One</a>
        <a href='pricing.html'>Invest</a>
      </div>
    </header>

    <section class='lead panel'>
      <h2 style='margin:0 0 6px 0'>Private sessions — a tuned approach for your agenda</h2>
      <p class='tiny' style='margin:0'>Work with sound and guided breath in a focused, confidential setting. We tailor tone, pacing, and language to your current state and aims.</p>
    </section>

    <div class='grid'>
      <div>
        <div class='panel'>
          <h3 style='margin-top:0'>Mood-to-Method</h3>
          <div class='tiny'>Pick how you feel; we’ll translate that into a short plan and an action-focused invitation.</div>
          <div style='margin-top:12px' class='selector' role='tablist' aria-label='Mood choices'>
            <button data-mode='tension' class='active'>Tension</button>
            <button data-mode='fog'>Mental fog</button>
            <button data-mode='ache'>Low energy</button>
            <button data-mode='ready'>Preparing</button>
          </div>

          <div style='margin-top:14px' class='method'>
            <h3 id='methodTitle'>Soften deep muscular holding</h3>
            <p id='methodDesc' class='tiny'>Long, low bowl tones with sustained exhalation cues to ease spinal and jaw holding. A brief movement release is included.</p>
            <div style='margin-top:8px'>
              <a id='bookCta' class='cta' href='book.html'>Book a session to unwind</a>
            </div>
          </div>

          <div class='disclaimer'>Before booking, note contraindications: if you are pregnant, have implanted devices, recent head injury, or epilepsy, consult with your care provider.</div>
        </div>

        <div class='panel' style='margin-top:12px'>
          <h4 style='margin:0 0 8px 0'>What to expect</h4>
          <ul style='margin:0;padding-left:18px;color:var(--muted)'>
            <li>30–90 minute options; custom pacing</li>
            <li>Short intake at start, grounding close</li>
            <li>Take-home cues and audio snippets for practice</li>
          </ul>
        </div>
      </div>

      <aside class='panel'>
        <div style='font-weight:700'>Session types</div>
        <div class='tiny' style='margin-top:8px;color:var(--muted)'>Choose a container that fits your goal.</div>
        <div style='margin-top:12px'>
          <div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:8px'>
            <div>
              <div style='font-weight:700'>Short Reset — 30m</div>
              <div class='tiny'>Targeted settling</div>
            </div>
            <div class='tiny'>35–</div>
          </div>
          <div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:8px'>
            <div>
              <div style='font-weight:700'>Deep Work — 60m</div>
              <div class='tiny'>Long tones and processing</div>
            </div>
            <div class='tiny'>75–</div>
          </div>
          <div style='display:flex;justify-content:space-between;align-items:center'>
            <div>
              <div style='font-weight:700'>Series Support — 5x</div>
              <div class='tiny'>Short series for stabilizing change</div>
            </div>
            <div class='tiny'>320–</div>
          </div>
        </div>
        <div style='margin-top:12px'><a class='cta' href='contact.html'>Request a consultation</a></div>

        <div style='margin-top:14px' class='tiny'>Questions? Call {{PHONE}}</div>
      </aside>
    </div>

    <footer style='margin-top:18px;color:var(--muted)'>
      <div>All sessions are facilitated with awareness and safety. Not a replacement for medical advice.</div>
    </footer>
  </div>

  <svg class='svg-decor' width='220' height='220' viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>
    <defs>
      <radialGradient id='r1' cx='30%' cy='20%'>
        <stop offset='0' stop-color='#FF7A9A'/>
        <stop offset='1' stop-color='#FFB3C9' stop-opacity='0.2'/>
      </radialGradient>
    </defs>
    <g fill='url(#r1)'>
      <circle cx='40' cy='40' r='28' />
      <circle cx='120' cy='90' r='18' />
      <circle cx='180' cy='160' r='40' />
    </g>
  </svg>

  <script>
    // Mood-to-Method logic
    const buttons = document.querySelectorAll(".selector button");
    const title = document.getElementById('methodTitle');
    const desc = document.getElementById('methodDesc');
    const cta = document.getElementById('bookCta');

    const methods = {
      tension: {title:'Soften deep muscular holding',desc:'Long low tones plus paced exhalations. A brief movement module helps release shoulder and jaw tension.',cta:'Book a session to unwind'},
      fog: {title:'Clear foggy thinking',desc:'High partials and voice-led sequencing to sharpen attention and restore clarity.',cta:'Schedule cognitive clearing'},
      ache: {title:'Rekindle energy',desc:'Short movement cues, rhythmic bowls, and breath pacing to revive circulation and bright mood.',cta:'Choose an energizing session'},
      ready: {title:'Prepare for change',desc:'A focused set to orient intention, with sound markers for transitions and short integration notes.',cta:'Reserve a preparatory session'}
    };

    buttons.forEach(b=>b.addEventListener('click',()=>{
      buttons.forEach(x=>x.classList.remove('active'));
      b.classList.add('active');
      const m = b.dataset.mode;
      const entry = methods[m];
      // gentle morph
      title.style.opacity=0;desc.style.opacity=0;cta.style.opacity=0;
      setTimeout(()=>{title.textContent=entry.title;desc.textContent=entry.desc;cta.textContent=entry.cta;title.style.opacity=1;desc.style.opacity=1;cta.style.opacity=1;},220);
    }));
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Invest — Pricing & Packages</title>
  <style>
    :root{--bg:#071627;--card:#071a2a;--accent:#3EE0C8;--muted:#9cc7d7}
    body{margin:0;font-family:Inter,ui-sans-serif,system-ui,Segoe UI,Roboto,Arial;color:#e8fbff;background:linear-gradient(180deg,var(--bg),#04121a);min-height:100vh}
    .wrap{max-width:980px;margin:28px auto;padding:22px}
    header{display:flex;justify-content:space-between;align-items:center}
    .logo{width:60px;height:60px;border-radius:12px;background:linear-gradient(135deg,#3EE0C8,#80ffd3);display:flex;align-items:center;justify-content:center;color:#003032;font-weight:800}
    nav a{color:#cfe8ff;text-decoration:none;margin-left:12px}
    .hero{margin-top:18px;padding:18px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .pricing-grid{display:flex;gap:18px;margin-top:18px}
    .plan{flex:1;padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .price{font-size:28px;font-weight:800;color:var(--accent)}
    .toggle{display:inline-flex;border-radius:999px;background:rgba(255,255,255,0.03);padding:6px}
    .toggle button{background:transparent;border:0;color:#cfe8ff;padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:var(--accent);color:#002b25}
    .muted{color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;background:var(--accent);color:#002b25;padding:10px 12px;border-radius:10px;text-decoration:none}
    .mini{font-size:13px;color:var(--muted)}
    .disclaimer{margin-top:12px;color:#ffd9d9;background:rgba(255,13,13,0.04);padding:10px;border-radius:8px}
  </style>
</head>
<body>
  <div class='wrap'>
    <header>
      <div style='display:flex;gap:12px;align-items:center'>
        <div class='logo'>PR</div>
        <div>
          <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
          <div style='font-size:12px;color:var(--muted)'>Offerings and time packages</div>
        </div>
      </div>
      <div>
        <a href='index.html'>Home</a>
        <a href='events.html'>Gatherings</a>
        <a href='private-sessions.html'>One-on-One</a>
        <a href='pricing.html'>Invest</a>
      </div>
    </header>

    <section class='hero'>
      <h1 style='margin:0 0 6px 0'>Clear pricing that matches how you want to show up</h1>
      <p class='mini' style='margin:0'>Choose between steady monthly access or a flexible session bundle. Toggle to compare totals and monthly-equivalents.</p>
      <div style='margin-top:14px'>
        <div class='toggle' role='tablist' aria-label='Pricing view'>
          <button id='monthlyBtn' class='active'>Monthly</button>
          <button id='packageBtn'>Package</button>
        </div>
      </div>
    </section>

    <div class='pricing-grid'>
      <div class='plan'>
        <div style='display:flex;justify-content:space-between;align-items:center'>
          <div>
            <div style='font-weight:700'>Ripple Access</div>
            <div class='mini muted'>Weekly small-group sessions + priority booking</div>
          </div>
          <div class='price' id='plan1'>$0</div>
        </div>
        <div style='margin-top:10px' class='mini muted'>Access to 4 group gatherings per month and one discounted private session.</div>
        <div><a id='plan1cta' class='cta' href='book.html'>Join the circle</a></div>
      </div>

      <div class='plan'>
        <div style='display:flex;justify-content:space-between;align-items:center'>
          <div>
            <div style='font-weight:700'>Solo Session</div>
            <div class='mini muted'>One-on-one tailored work</div>
          </div>
          <div class='price' id='plan2'>$0</div>
        </div>
        <div style='margin-top:10px' class='mini muted'>A single focused session for a pressing need or preparation.</div>
        <div><a id='plan2cta' class='cta' href='book.html'>Book a private session</a></div>
      </div>

      <div class='plan'>
        <div style='display:flex;justify-content:space-between;align-items:center'>
          <div>
            <div style='font-weight:700'>Series Packet</div>
            <div class='mini muted'>5-session pack for sustained change</div>
          </div>
          <div class='price' id='plan3'>$0</div>
        </div>
        <div style='margin-top:10px' class='mini muted'>Best for steady shifts — save on individual session pricing.</div>
        <div><a id='plan3cta' class='cta' href='book.html'>Choose a pack</a></div>
      </div>
    </div>

    <div style='margin-top:16px' class='panel' aria-hidden='false'>
      <div style='color:var(--muted)'>Toggle detail: prices animate when switching view. Monthly shows recurring rate, Package shows up-front bundle total and per-session equivalent.</div>
      <div class='disclaimer'>If you have health conditions (pregnancy, epilepsy, implanted devices, recent head trauma), please consult before booking.</div>
    </div>

    <footer style='margin-top:18px;color:var(--muted)'>Questions: {{EMAIL}} • {{PHONE}}</footer>
  </div>

  <script>
    // Pricing comparator data
    const prices = {
      monthly: {plan1:40, plan2:75, plan3:55}, // plan3 per-session monthly-equivalent
      package: {plan1:120, plan2:75, plan3:280} // package totals
    };

    let view = 'monthly';
    const monthlyBtn = document.getElementById('monthlyBtn');
    const packageBtn = document.getElementById('packageBtn');
    const p1 = document.getElementById('plan1');
    const p2 = document.getElementById('plan2');
    const p3 = document.getElementById('plan3');

    function animateNumber(el, start, end, duration=450){
      const startTime = performance.now();
      function tick(now){
        const t = Math.min(1,(now-startTime)/duration);
        const val = Math.round(start + (end-start)*t);
        el.textContent = (view==='monthly' ? ('$'+val) : ('$'+val));
        if(t<1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    function setView(v){
      view=v;
      if(v==='monthly'){
        monthlyBtn.classList.add('active');packageBtn.classList.remove('active');
        animateNumber(p1,parseInt(p1.textContent.replace('$',''))||0,prices.monthly.plan1);
        animateNumber(p2,parseInt(p2.textContent.replace('$',''))||0,prices.monthly.plan2);
        animateNumber(p3,parseInt(p3.textContent.replace('$',''))||0,prices.monthly.plan3);
        document.getElementById('plan1cta').textContent='Join monthly';
        document.getElementById('plan2cta').textContent='Book one-off';
        document.getElementById('plan3cta').textContent='Start monthly series';
      } else {
        packageBtn.classList.add('active');monthlyBtn.classList.remove('active');
        animateNumber(p1,parseInt(p1.textContent.replace('$',''))||0,prices.package.plan1);
        animateNumber(p2,parseInt(p2.textContent.replace('$',''))||0,prices.package.plan2);
        animateNumber(p3,parseInt(p3.textContent.replace('$',''))||0,prices.package.plan3);
        document.getElementById('plan1cta').textContent='Buy a month up front';
        document.getElementById('plan2cta').textContent='Purchase single session';
        document.getElementById('plan3cta').textContent='Buy the 5-session pack';
      }
    }

    monthlyBtn.addEventListener('click',()=>setView('monthly'));
    packageBtn.addEventListener('click',()=>setView('package'));

    // initialize
    setTimeout(()=>setView('monthly'),80);
  </script>
</body>
